// Generated by Cypress Author on 2026-10-18
//
// A public Instagram post references one public and one private drive video.
// The owner can preview both. Another viewer gets the public preview and one
// non-disclosing fallback for the private object.

import { replaceVisualText } from "../support/mdxEditor.js";
import {
  bucketNameFrom,
  makeObjectPublic,
  namedFixture,
  openDrive,
  readOwnRow,
  uploadThroughDialog,
  type StoredObject,
} from "../support/driveObjects.js";

const PUBLIC_VIDEO = "cypress/fixtures/testFiles/storage-tile-preview.mp4";
const PRIVATE_IMAGE = "cypress/fixtures/testFiles/WIN_20260102_21_30_21_Pro.jpg";

function postArticle(marker: string) {
  return cy.contains("[data-cy='igPosts_item']", marker, { timeout: 30000 });
}

function referenceTile(marker: string, caption: string, timeout = 45000) {
  return postArticle(marker).contains(
    "[data-cy='storage_reference_tile']",
    caption,
    { timeout },
  );
}

function loadedImage(tile: Cypress.Chainable<JQuery<HTMLElement>>) {
  tile.scrollIntoView();
  tile
    .find("[data-cy='dStorage_thumbnail_image']", { timeout: 60000 })
    .should(($image) => {
      const image = $image[0] as HTMLImageElement | undefined;
      expect(image?.complete, "poster complete").to.eq(true);
      expect(image?.naturalWidth ?? 0, "poster width").to.be.greaterThan(0);
      const surface = image?.closest("[data-cy='dStorage_thumbnail']");
      expect(surface, "thumbnail surface").to.exist;
      const imageBox = image!.getBoundingClientRect();
      const surfaceBox = surface!.getBoundingClientRect();
      expect(imageBox.top, "poster top").to.be.closeTo(surfaceBox.top, 1);
      expect(imageBox.left, "poster left").to.be.closeTo(surfaceBox.left, 1);
      expect(imageBox.width, "poster width").to.be.closeTo(surfaceBox.width, 1);
      expect(imageBox.height, "poster height").to.be.closeTo(
        surfaceBox.height,
        1,
      );
    });
}

describe("instagram storage references", () => {
  beforeEach(() => {
    cy.viewport("macbook-13");
  });

  it("submits a public and a private reference → the other viewer only sees the public preview", () => {
    cy.uniqueRecordName("embed").then((marker) => {
      const publicFile = namedFixture(PUBLIC_VIDEO, `${marker}-public`);
      const privateFile = namedFixture(PRIVATE_IMAGE, `${marker}-private`);

      openDrive(0, "mine");
      uploadThroughDialog(publicFile);
      uploadThroughDialog(privateFile);
      makeObjectPublic(publicFile.fileName);

      cy.get("@listObjects").then((interception) => {
        const listed = interception as unknown as { request: { url: string } };
        const bucket = bucketNameFrom(listed.request.url);
        readOwnRow(bucket, publicFile.fileName).as("publicObject");
        readOwnRow(bucket, privateFile.fileName).as("privateObject");
      });

      cy.get("@publicObject").then((publicObject) => {
        cy.get("@privateObject").then((privateObject) => {
          const published = publicObject as unknown as StoredObject;
          const hidden = privateObject as unknown as StoredObject;
          const markdown = [
            marker,
            `![public clip](uploads://${published.storageObjectId})`,
            `![private clip](uploads://${hidden.storageObjectId})`,
          ].join("{enter}{enter}");

          cy.intercept("POST", "/api/views/igPosts/new/item").as("createPost");
          cy.visit("/instagreg/home");
          cy.waitForClerkLoaded();
          cy.get("[data-cy='p_text_content_field'] [data-cy='mdx-visual-editor']", {
            timeout: 20000,
          }).should("exist");
          replaceVisualText("p_text_content_field", markdown);
          cy.get("[data-cy='create_ig_post_submit']").click();
          cy.wait("@createPost")
            .its("request.body")
            .should((body: unknown) => {
              const encoded = typeof body === "string" ? body : JSON.stringify(body);
              expect(encoded).to.contain(
                `![public clip](uploads://${published.storageObjectId})`,
              );
              expect(encoded).to.contain(
                `![private clip](uploads://${hidden.storageObjectId})`,
              );
            });

          loadedImage(referenceTile(marker, "public clip"));
          loadedImage(referenceTile(marker, "private clip"));
          postArticle(marker)
            .find("[data-cy='storage_reference_unavailable']")
            .should("not.exist");

          cy.signInAsUser(1);
          cy.intercept("POST", "/api/storage/references").as("resolveReference");
          cy.intercept("GET", /\/api\/jobs\/[^/?]+$/).as("jobPoll");
          cy.visit("/instagreg/home");
          cy.waitForClerkLoaded();
          loadedImage(referenceTile(marker, "public clip"));
          postArticle(marker)
            .find("[data-cy='storage_reference_unavailable']")
            .should("have.length", 1)
            .and("have.text", "Attachment unavailable")
            .and("not.have.attr", "tabindex");
          postArticle(marker).should("not.contain", privateFile.fileName);
          postArticle(marker).should("not.contain", hidden.s3ObjectKey);
          const publicPreview = () =>
            referenceTile(marker, "public clip").find(
              `[aria-label="Preview ${publicFile.fileName}"]`,
            );
          publicPreview().trigger("pointerover", {
            eventConstructor: "PointerEvent",
            bubbles: true,
          });
          publicPreview()
            .find("[data-cy='dStorage_thumbnail_animation']", { timeout: 45000 })
            .should("be.visible");
          publicPreview().trigger("pointerout", {
            eventConstructor: "PointerEvent",
            bubbles: true,
          });
          publicPreview()
            .find("[data-cy='dStorage_thumbnail_animation']")
            .should("not.exist");
          publicPreview().focus();
          publicPreview()
            .find("[data-cy='dStorage_thumbnail_animation']", { timeout: 45000 })
            .should("be.visible");
          postArticle(marker)
            .find("[data-cy='storage_reference_unavailable']")
            .should("not.have.attr", "tabindex");

          cy.get("@jobPoll.all").should((interceptions) => {
            const bodies = (interceptions as unknown as Array<{ response?: { body?: unknown } }>).map(
              (item) => JSON.stringify(item.response?.body ?? {}),
            );
            for (const body of bodies) {
              expect(body).not.to.contain(hidden.s3ObjectKey);
              expect(body).not.to.contain(privateFile.fileName);
            }
          });
        });
      });
    });
  });

  // Generated by Cypress Author on 2026-10-18.
  // A completed preview keeps its result object and signs a new URL on each
  // later read. Rejecting the first signature must not leave the MP4 fallback.
  it("reopens a post that embeds a video → the poster is shown again", () => {
    cy.uniqueRecordName("reopen").then((marker) => {
      const publicFile = namedFixture(PUBLIC_VIDEO, `${marker}-public`);

      openDrive(0, "mine");
      uploadThroughDialog(publicFile);
      makeObjectPublic(publicFile.fileName);

      cy.get("@listObjects").then((interception) => {
        const listed = interception as unknown as { request: { url: string } };
        const bucket = bucketNameFrom(listed.request.url);
        readOwnRow(bucket, publicFile.fileName).as("publicObject");
      });

      cy.get("@publicObject").then((publicObject) => {
        const published = publicObject as unknown as StoredObject;
        const markdown = [
          marker,
          `![public clip](uploads://${published.storageObjectId})`,
        ].join("{enter}{enter}");

        cy.intercept("POST", "/api/views/igPosts/new/item").as("createPost");
        cy.visit("/instagreg/home");
        cy.waitForClerkLoaded();
        cy.get("[data-cy='p_text_content_field'] [data-cy='mdx-visual-editor']", {
          timeout: 20000,
        }).should("exist");
        replaceVisualText("p_text_content_field", markdown);
        cy.get("[data-cy='create_ig_post_submit']").click();
        cy.wait("@createPost")
          .its("request.body")
          .should((body: unknown) => {
            const encoded = typeof body === "string" ? body : JSON.stringify(body);
            expect(encoded).to.contain(
              `![public clip](uploads://${published.storageObjectId})`,
            );
          });

        const tile = () => referenceTile(marker, "public clip");
        loadedImage(tile());
        tile()
          .find("[data-cy='dStorage_thumbnail_image']")
          .invoke("attr", "src")
          .should("match", /^https?:\/\//)
          .then((src) => {
            const first = String(src);
            const escaped = first.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
            cy.intercept("GET", new RegExp(`^${escaped}$`), {
              statusCode: 403,
              body: "",
            });
            // SigV4 dates change by the second. Wait so the reloaded read
            // cannot reuse the same signature by coincidence.
            cy.wait(1100);
            cy.reload(true);
            cy.waitForClerkLoaded();
            // The single worker may still be finishing the previous post's
            // preview, so this read waits longer than the first paint.
            const reopened = () => referenceTile(marker, "public clip", 90000);
            loadedImage(reopened());
            reopened().find("[data-cy='dStorage_thumbnail_fallback']").should("not.exist");
            reopened()
              .find("[data-cy='dStorage_thumbnail_image']")
              .invoke("attr", "src")
              .should("match", /^https?:\/\//)
              .and("not.equal", first);
          });
      });
    });
  });
});
